        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.sma_period = 20
        self.spy_closes = deque(maxlen=self.sma_period + 1)
        self.previous_aapl_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = self.RSI(
            self.symbols["AAPL"],
            14,
            MovingAverageType.Wilders,
            Resolution.Daily,
        )

        self.spy_lot = 0
        self.aapl_lot = 0

    def OnData(self, data):
        bars = data.Bars

        spy_bar = bars[self.symbols["SPY"]] if bars.ContainsKey(self.symbols["SPY"]) else None
        aapl_bar = bars[self.symbols["AAPL"]] if bars.ContainsKey(self.symbols["AAPL"]) else None

        if spy_bar is not None:
            self.spy_closes.append(float(spy_bar.Close))

        if aapl_bar is not None:
            aapl_close = float(aapl_bar.Close)
            if self.previous_aapl_close is None or aapl_close >= self.previous_aapl_close:
                self.aapl_red_streak = 0
            else:
                self.aapl_red_streak += 1
            self.previous_aapl_close = aapl_close

        if any(not bars.ContainsKey(symbol) for symbol in self.symbols.values()):
            return

        self.RunSpyStrategy(float(spy_bar.Close))
        self.RunAaplStrategy(float(aapl_bar.Close))

    def RunSpyStrategy(self, close):
        if len(self.spy_closes) < self.sma_period + 1:
            return

        closes = list(self.spy_closes)
        yesterday_close = closes[-2]
        yesterday_sma = sum(closes[-self.sma_period - 1:-1]) / self.sma_period
        today_sma = sum(closes[-self.sma_period:]) / self.sma_period

        crossed_below = yesterday_close >= yesterday_sma and close < today_sma
        crossed_above = yesterday_close <= yesterday_sma and close > today_sma

        if self.spy_lot > 0:
            if crossed_below:
                self.MarketOrder(self.symbols["SPY"], -self.spy_lot)
                self.spy_lot = 0
            return

        if crossed_above:
            quantity = floor(0.40 * float(self.Portfolio.TotalPortfolioValue) / close)
            if quantity > 0:
                self.MarketOrder(self.symbols["SPY"], quantity)
                self.spy_lot = quantity

    def RunAaplStrategy(self, close):
        if not self.aapl_rsi.IsReady:
            return

        if self.aapl_lot > 0:
            if float(self.aapl_rsi.Current.Value) > 60:
                self.MarketOrder(self.symbols["AAPL"], -self.aapl_lot)
                self.aapl_lot = 0
            return

        if self.aapl_red_streak >= 3 and float(self.Portfolio.Cash) >= 20_000:
            quantity = floor(20_000 / close)
            if quantity > 0:
                self.MarketOrder(self.symbols["AAPL"], quantity)
                self.aapl_lot = quantity

