class IndependentSpyAaplStrategies(QCAlgorithm):
    """Two independent daily strategies with separately tracked share lots."""

    SPY_SMA_PERIOD = 20
    AAPL_RSI_PERIOD = 14

    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.add_equity(
                ticker, Resolution.DAILY
            ).symbol

        self.spy_closes = deque(maxlen=self.SPY_SMA_PERIOD + 1)
        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(
            self.AAPL_RSI_PERIOD, MovingAverageType.WILDERS
        )

        self.spy_lot = 0
        self.aapl_lot = 0

    def on_data(self, data: Slice):
        bars = data.bars
        available = {
            ticker: bars[symbol]
            for ticker, symbol in self.symbols.items()
            if bars.contains_key(symbol)
        }

        spy_bar = available.get("SPY")
        if spy_bar is not None:
            self.spy_closes.append(float(spy_bar.close))

        aapl_bar = available.get("AAPL")
        if aapl_bar is not None:
            aapl_close = float(aapl_bar.close)
            if self.aapl_previous_close is not None:
                if aapl_close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_previous_close = aapl_close
            self.aapl_rsi.update(aapl_bar.end_time, aapl_bar.close)

        if len(available) != len(self.symbols):
            return

        # Each independent strategy evaluates its exit before its entry.
        self._evaluate_spy(float(spy_bar.close))
        self._evaluate_aapl(float(aapl_bar.close))

    def _evaluate_spy(self, close):
        if len(self.spy_closes) < self.SPY_SMA_PERIOD + 1:
            return

        closes = list(self.spy_closes)
        previous_close = closes[-2]
        previous_sma = sum(closes[-self.SPY_SMA_PERIOD - 1:-1]) / self.SPY_SMA_PERIOD
        current_sma = sum(closes[-self.SPY_SMA_PERIOD:]) / self.SPY_SMA_PERIOD

        crosses_below = previous_close >= previous_sma and close < current_sma
        crosses_above = previous_close <= previous_sma and close > current_sma

        if self.spy_lot > 0:
            if crosses_below:
                self.market_order(self.symbols["SPY"], -self.spy_lot)
                self.spy_lot = 0
            return

        if crosses_above:
            target_value = 0.40 * float(self.portfolio.total_portfolio_value)
            quantity = floor(target_value / close)
            if quantity > 0:
                self.market_order(self.symbols["SPY"], quantity)
                self.spy_lot = quantity

    def _evaluate_aapl(self, close):
        if not self.aapl_rsi.is_ready:
            return

        if self.aapl_lot > 0:
            if float(self.aapl_rsi.current.value) > 60:
                self.market_order(self.symbols["AAPL"], -self.aapl_lot)
                self.aapl_lot = 0
            return

        if self.aapl_red_streak >= 3:
            purchase_value = 20_000
            if float(self.portfolio.cash) >= purchase_value:
                quantity = floor(purchase_value / close)
                if quantity > 0:
                    self.market_order(self.symbols["AAPL"], quantity)
                    self.aapl_lot = quantity

