        )

        self.previous_closes = {}
        self.previous_spy_sma = None
        self.aapl_red_streak = 0

        # Quantities are tracked by strategy, rather than inferred from the
        # aggregate security holding, so each strategy owns only its own lot.
        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def on_data(self, data: Slice):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if data.bars.contains_key(symbol):
                bars[ticker] = data.bars[symbol]

        # Market-state quantities continue to consume each ticker's own data,
        # even on a day whose incomplete universe prevents rule evaluation.
        if "AAPL" in bars:
            aapl_close = bars["AAPL"].close
            previous_aapl_close = self.previous_closes.get("AAPL")
            if previous_aapl_close is None:
                self.aapl_red_streak = 0
            elif aapl_close < previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0
            self.aapl_rsi.update(self.time, aapl_close)

        if "SPY" in bars:
            self.spy_sma.update(self.time, bars["SPY"].close)

        complete_day = len(bars) == len(self.symbols)
        if not complete_day:
            for ticker, bar in bars.items():
                self.previous_closes[ticker] = bar.close
            if "SPY" in bars and self.spy_sma.is_ready:
                self.previous_spy_sma = self.spy_sma.current.value
            return

        spy_close = bars["SPY"].close
        aapl_close = bars["AAPL"].close

