        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.aapl_red_streak = 0

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def OnData(self, data: Slice):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if data.Bars.ContainsKey(symbol):
                bars[ticker] = data.Bars[symbol]

        # Market-state quantities are updated whenever their ticker has a bar,
        # even on a day on which trading must be skipped due to another missing bar.
        spy_close = None
        spy_sma_value = None
        if "SPY" in bars:
            spy_close = bars["SPY"].Close
            self.spy_sma.Update(bars["SPY"].EndTime, spy_close)
            if self.spy_sma.IsReady:
                spy_sma_value = self.spy_sma.Current.Value

        if "AAPL" in bars:
            aapl_close = bars["AAPL"].Close
            previous_aapl_close = self.previous_closes.get("AAPL")
            if previous_aapl_close is not None:
                if aapl_close < previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_rsi.Update(bars["AAPL"].EndTime, aapl_close)

        complete_day = len(bars) == len(self.symbols)
        if complete_day:
            self._evaluate_strategy_a(spy_close, spy_sma_value)
            self._evaluate_strategy_b(bars["AAPL"].Close)

        if spy_sma_value is not None:
            self.previous_spy_close = spy_close
            self.previous_spy_sma = spy_sma_value

