        spy_crossed_below = (
            spy_previous_difference is not None
            and spy_difference is not None
            and spy_previous_difference >= 0
            and spy_difference < 0
        )
        spy_crossed_above = (
            spy_previous_difference is not None
            and spy_difference is not None
            and spy_previous_difference <= 0
            and spy_difference > 0
        )

