        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_closes = deque(maxlen=self.SMA_PERIOD)
        self.spy_previous_close = None
        self.spy_previous_sma = None

        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(
            self.RSI_PERIOD, MovingAverageType.Wilders
        )

        self.spy_lot = 0
        self.aapl_lot = 0
        self.spy_order_pending = False
        self.aapl_order_pending = False
        self.order_strategies = {}

    def OnData(self, data):
        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        current_spy_sma = None
        if spy in data.Bars:
            spy_close = float(data.Bars[spy].Close)
            self.spy_closes.append(spy_close)
            if len(self.spy_closes) == self.SMA_PERIOD:
                current_spy_sma = sum(self.spy_closes) / self.SMA_PERIOD

        if aapl in data.Bars:
            aapl_close = float(data.Bars[aapl].Close)
            if self.aapl_previous_close is not None:
                if aapl_close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_rsi.Update(data.Bars[aapl].EndTime, aapl_close)

        all_bars_present = all(
            symbol in data.Bars for symbol in self.symbols.values()
        )
        all_state_ready = (
            current_spy_sma is not None
            and self.spy_previous_close is not None
            and self.spy_previous_sma is not None
            and self.aapl_previous_close is not None
            and self.aapl_rsi.IsReady
        )

        if all_bars_present and all_state_ready:
            spy_close = float(data.Bars[spy].Close)
            aapl_close = float(data.Bars[aapl].Close)

            # Sells are evaluated before buys.
            if self.spy_lot > 0 and not self.spy_order_pending:
                crosses_below = (
                    self.spy_previous_close >= self.spy_previous_sma
                    and spy_close < current_spy_sma
                )
                if crosses_below:
                    self._submit_order(spy, -self.spy_lot, "spy")

            if self.aapl_lot > 0 and not self.aapl_order_pending:
                if float(self.aapl_rsi.Current.Value) > 60:
                    self._submit_order(aapl, -self.aapl_lot, "aapl")

            if self.spy_lot == 0 and not self.spy_order_pending:
                crosses_above = (
                    self.spy_previous_close <= self.spy_previous_sma
                    and spy_close > current_spy_sma
                )
                if crosses_above:
                    shares = math.floor(
                        0.40 * float(self.Portfolio.TotalPortfolioValue) / spy_close
                    )
                    if shares > 0:
                        self._submit_order(spy, shares, "spy")

            if self.aapl_lot == 0 and not self.aapl_order_pending:
                if self.aapl_red_streak >= 3 and float(self.Portfolio.Cash) >= 20_000:
                    shares = math.floor(20_000 / aapl_close)
                    if shares > 0:
                        self._submit_order(aapl, shares, "aapl")

        if spy in data.Bars and current_spy_sma is not None:
            self.spy_previous_close = float(data.Bars[spy].Close)
            self.spy_previous_sma = current_spy_sma
        elif spy in data.Bars:
            self.spy_previous_close = float(data.Bars[spy].Close)

        if aapl in data.Bars:
            self.aapl_previous_close = float(data.Bars[aapl].Close)

    def _submit_order(self, symbol, quantity, strategy):
        ticket = self.MarketOrder(symbol, quantity)
        self.order_strategies[ticket.OrderId] = strategy
        if strategy == "spy":
            self.spy_order_pending = True
        else:
            self.aapl_order_pending = True

    def OnOrderEvent(self, order_event):
        strategy = self.order_strategies.get(order_event.OrderId)
        if strategy is None:
            return

        if order_event.Status in (OrderStatus.PartiallyFilled, OrderStatus.Filled):
            fill_quantity = int(order_event.FillQuantity)
            if strategy == "spy":
                self.spy_lot = max(0, self.spy_lot + fill_quantity)
            else:
                self.aapl_lot = max(0, self.aapl_lot + fill_quantity)

        if order_event.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid,
        ):
            if strategy == "spy":
                self.spy_order_pending = False
            else:
                self.aapl_order_pending = False
            del self.order_strategies[order_event.OrderId]

