            )

            # Evaluate every sell before evaluating either strategy's buy.
            if self.spy_lot_open and spy_crossed_below:
                quantity = self.portfolio[self.spy].quantity
                if quantity != 0:
                    self.market_order(self.spy, -quantity)
                self.spy_lot_open = False

            if self.aapl_lot_open and self.aapl_rsi.current.value > 60:
                quantity = self.portfolio[self.aapl].quantity
                if quantity != 0:
                    self.market_order(self.aapl, -quantity)
                self.aapl_lot_open = False

            spy_crossed_above = (
                self.previous_spy_close <= self.previous_spy_sma
                and spy_close > spy_sma
            )
            if not self.spy_lot_open and spy_crossed_above:
                quantity = int(
                    (self.portfolio.total_portfolio_value * 0.40) // spy_close
                )
                if quantity > 0:
                    self.market_order(self.spy, quantity)
                    self.spy_lot_open = True

            if not self.aapl_lot_open and self.aapl_red_streak >= 3:
                allocation = 20_000
                if self.portfolio.cash >= allocation:
                    quantity = int(allocation // aapl_bar.close)
                    if quantity > 0:
                        self.market_order(self.aapl, quantity)
                        self.aapl_lot_open = True

        if spy_bar is not None and self.spy_sma.is_ready:
            self.previous_spy_close = spy_bar.close
            self.previous_spy_sma = self.spy_sma.current.value

